interface Movable { var position: Position }        // capability interface

// the servant: top-level extension functions, member syntax at the call site
fun Movable.moveTo(to: Position) { position = to }
fun Movable.moveBy(dx: Int, dy: Int) { moveTo(position.shifted(dx, dy)) }

// generic servant over every type with the capability
fun <T : Movable> List<T>.moveAllTo(to: Position) = forEach { it.moveTo(to) }

